def _kvpr(mlist):
    """KVPR of one GPU's model list."""
    free = GPU_MEM_SIZE - sum(m.model_size for m in mlist)
    if not mlist or free <= 0:
        return 0.0
    return sum(m.req_rate / m.slo for m in mlist) / free


def _greedy(gpu_num, sorted_models, by_result):
    """Greedy placement; each model goes to the fittable GPU with lowest
    current KVPR (by_result=False) or lowest resulting KVPR (by_result=True)."""
    placement = {i: [] for i in range(gpu_num)}
    free = [GPU_MEM_SIZE] * gpu_num
    load = [0.0] * gpu_num
    for m in sorted_models:
        best_idx, best = None, float('inf')
        for g in range(gpu_num):
            if m.model_size <= free[g] and free[g] - m.model_size > 0:
                v = (load[g] + m.req_rate / m.slo) / (free[g] - m.model_size) \
                    if by_result else load[g] / free[g]
                if v < best:
                    best, best_idx = v, g
        if best_idx is None:
            return None
        placement[best_idx].append(m)
        load[best_idx] += m.req_rate / m.slo
        free[best_idx] -= m.model_size
    return placement


def _refine(p):
    """Hill-climb: move a model off the worst-KVPR GPU when it lowers max KVPR."""
    for _ in range(len(p) * 4):
        k = {g: _kvpr(p[g]) for g in p}
        src = max(p, key=lambda g: k[g])
        if k[src] <= 0:
            break
        improved = False
        for m in list(p[src]):
            for dst in p:
                if dst == src:
                    continue
                if m.model_size > GPU_MEM_SIZE - sum(x.model_size for x in p[dst]):
                    continue
                p[src].remove(m); p[dst].append(m)
                nk = {g: _kvpr(p[g]) for g in p}
                if max(nk.values()) < max(k.values()) - 1e-12:
                    k, improved = nk, True
                    break
                p[dst].remove(m); p[src].append(m)
            if improved:
                break
        if not improved:
            break
    return p


def compute_model_placement(gpu_num, models):
    """
    Best-of-4 greedy placement minimizing max KVPR: try greedy under two
    orderings (pressure desc, size desc) x two GPU-choice rules (lowest
    current KVPR, lowest resulting KVPR), refine each with a local-search
    pass moving models off the worst GPU, and return the best placement.
    """
    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
    ]
    best, best_max = None, float('inf')
    for ms in orders:
        for by_result in (False, True):
            p = _greedy(gpu_num, ms, by_result)
            if p is None:
                continue
            p = _refine(p)
            mx = max(_kvpr(ml) for ml in p.values())
            if mx < best_max:
                best, best_max = p, mx
    if best is None:
        raise ValueError("Unable to place all models within GPU memory")
    return best

